CREATE TABLE notification_deliveries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL, template_key VARCHAR(64) NOT NULL, payload_cipher LONGTEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'QUEUED', attempts INT UNSIGNED NOT NULL DEFAULT 0, next_attempt_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, last_error VARCHAR(100) NULL, sent_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(template_key) REFERENCES notification_templates(template_key), INDEX(status,next_attempt_at), CHECK(status IN ('QUEUED','SENT','FAILED'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
